def _migrate_data() -> None:
    """Preserves existing data: per-user VPN accounts become devices; the legacy welcome text and
    never-configured legacy plans are removed."""
    conn = op.get_bind()
    accounts = conn.execute(sa.text(
        "SELECT a.user_id, a.provider, a.external_id, a.status, a.created_at, s.id "
        "FROM vpn_accounts a LEFT JOIN subscriptions s ON s.user_id = a.user_id"
    )).fetchall()
    for user_id, provider, external_id, status, created_at, sub_id in accounts:
        conn.execute(sa.text(
            "INSERT INTO devices (public_id, user_id, subscription_id, name, status, provider, external_username, "
            "external_id, sync_needed, created_at, updated_at) VALUES (:pid, :uid, :sid, :name, :status, :provider, "
            ":username, :ext, :sync, :created, :created)"
        ), {"pid": str(uuid.uuid4()), "uid": user_id, "sid": sub_id, "name": "Основное устройство",
            "status": "active" if status == "active" else "suspended", "provider": provider,
            "username": external_id, "ext": external_id, "sync": False, "created": created_at})
    op.drop_table('vpn_accounts')
    conn.execute(sa.text(
        "DELETE FROM settings WHERE key = 'welcome_text' AND (value LIKE '%Добро пожаловать%' "
        "OR value LIKE '%Твой VPN начинается здесь%')"
    ))
    conn.execute(sa.text(
        "DELETE FROM plans WHERE code IN ('m1', 'm3', 'm6', 'm12') AND price = 0 "
        "AND id NOT IN (SELECT plan_id FROM orders WHERE plan_id IS NOT NULL)"
    ))


